{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Dutasteride, a lipophilic steroid-like molecule, has an absolute oral bioavailability of approximately 60% (range 40–94%) in humans, demonstrating that steroid scaffolds with bulky lipophilic substituents can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Esaxerenone, which contains the same p-methylsulfonylphenyl moiety as the query, showed 89.0% absolute oral bioavailability in fasting healthy Japanese subjects after a 5 mg oral dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Odanacatib, a p-methylsulfonylphenyl- and CF3-containing compound, had 30% absolute oral bioavailability at the 50 mg fasted dose (90% CI 27–34%), still above the 20% threshold, and 70% at 10 mg.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Ethinylestradiol, a small steroid, has a mean absolute oral bioavailability of 55% across six human studies, supporting high oral F for steroid-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Cilomilast, a lipophilic oral drug with polar functionality, was almost completely bioavailable (96%, range 92–102%) in humans, showing that polar groups do not preclude high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Danazol, a structurally related steroid, had only 11 ± 5.2% absolute oral bioavailability in the fasted state in humans, indicating that some lipophilic steroids can fall below the 20% threshold due to solubility-limited absorption.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: multiple high-transfer analogs with steroid scaffolds or p-methylsulfonylphenyl/CF3 motifs show absolute oral bioavailability of 30–96% in humans. The only sub-20% analog (danazol fasted) is solubility-limited, and the query's polar sulfone is expected to mitigate that limitation; no direct low-F evidence applies to the query.",
  "evidence_gaps": [
    "No direct human oral bioavailability data for the query molecule.",
    "Fasted/fed conditions and dose for the query are unspecified; food effects can shift F across the 20% threshold.",
    "Potential inhaled/soft-drug design intent is not directly captured by the available analogs."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

